    @media (max-width: 480px) { form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main>
    <section id="list-view" hidden>
      <h1>Workboard</h1>
      <form id="create-form" novalidate>
        <label for="project-name">Project name</label>
        <input id="project-name" name="name" type="text" aria-label="Project name">
        <button type="submit">Create project</button>
      </form>
      <label for="project-filter">Project filter</label>
      <select id="project-filter" aria-label="Project filter">
        <option value="active">Active</option><option value="archived">Archived</option>
      </select>
      <div id="alert" role="alert" aria-live="polite"></div>
      <div id="projects"></div>
    </section>
    <section id="detail" hidden>
      <button id="back" type="button">Projects</button>
      <p id="archived-notice" hidden>Archived project</p>
      <h1 id="detail-name"></h1>
      <form id="rename-form" novalidate>
        <label for="new-project-name">New project name</label>
        <input id="new-project-name" name="name" type="text" aria-label="New project name">
        <button type="submit">Rename project</button>
      </form>
      <div id="rename-alert" role="alert" aria-live="polite"></div>
      <form id="task-form" novalidate>
        <label for="task-title-input">Task title</label>
        <input id="task-title-input" name="title" type="text" aria-label="Task title">
        <button type="submit">Create task</button>
      </form>
      <div id="task-alert" role="alert" aria-live="polite"></div>
      <label for="task-filter">Task filter</label>
      <select id="task-filter" aria-label="Task filter">
        <option>All</option><option>Open</option><option>Completed</option>
      </select>
      <div id="tasks"></div>
    </section>
  </main>
  <script>
    const listView = document.querySelector('#list-view');
    const detail = document.querySelector('#detail');
    const projects = document.querySelector('#projects');
    const alertBox = document.querySelector('#alert');
    const tasks = document.querySelector('#tasks');
    const taskAlert = document.querySelector('#task-alert');
    let activeProjectId = null;
    let activeProjectArchived = false;

    async function loadProjects() {
      const archived = document.querySelector('#project-filter').value === 'archived';
      const response = await fetch(`/api/projects?archived=${archived}`);
      return response.json();
    }

    async function showList() {
      listView.hidden = false;
      detail.hidden = true;
      const items = await loadProjects();
      projects.replaceChildren(...items.map(project => {
        const row = document.createElement('div');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.className = 'project-name';
        name.textContent = project.name;
        const open = document.createElement('button');
        open.type = 'button';
        open.textContent = 'Open project';
        open.addEventListener('click', () => navigate(`/projects/${project.id}`));
        const summary = document.createElement('span');
        summary.className = 'project-summary';
        summary.dataset.testid = 'project-summary';
        summary.textContent = `${project.completed_count}/${project.total_count} completed`;
        const actions = document.createElement('div');
        actions.className = 'project-actions';
        actions.append(summary, open);
        const archive = document.createElement('button');
        archive.type = 'button';
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          const action = project.archived ? 'restore' : 'archive';
          const response = await fetch(`/api/projects/${project.id}/${action}`, { method: 'POST' });
          if (response.ok) await showList();
        });
        actions.append(archive);
        row.append(name, actions);
        return row;
      }));
    }

    async function showProject(id) {
      listView.hidden = true;
      detail.hidden = false;
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) {
        history.replaceState({}, '', '/');
        await showList();
        return;
      }
      const project = await response.json();
      activeProjectId = id;
      document.querySelector('#detail-name').textContent = project.name;
      const isArchived = !!project.archived;
      activeProjectArchived = isArchived;
      document.querySelector('#archived-notice').hidden = !isArchived;
      document.querySelector('#new-project-name').disabled = isArchived;
      document.querySelector('#rename-form').querySelector('button').disabled = isArchived;
      document.querySelector('#task-title-input').disabled = isArchived;
      document.querySelector('#task-form').querySelector('button').disabled = isArchived;
      await loadTasks();
    }

    async function loadTasks() {
      if (!activeProjectId) return;
      const response = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`);
      if (!response.ok) return;
      const allTasks = await response.json();
      const filter = document.querySelector('#task-filter').value;
      const visible = allTasks.filter(task => filter === 'All' || (filter === 'Open' ? !task.completed : !!task.completed));
      tasks.replaceChildren(...visible.map(task => {
        const row = document.createElement('div');
        row.className = 'task-row';
        row.dataset.testid = 'task-row';
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = !!task.completed;
        checkbox.disabled = !!(document.querySelector('#archived-notice').hidden === false);
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          const result = await fetch(`/api/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked })
          });
          if (result.ok) await loadTasks();
        });
        const title = document.createElement('span');
        title.className = 'task-title';
        title.textContent = task.title;
        const renameForm = document.createElement('form');
        renameForm.className = 'task-rename-form';
        renameForm.noValidate = true;
        const renameInput = document.createElement('input');
        renameInput.type = 'text';
        renameInput.setAttribute('aria-label', 'New task title');
        renameInput.value = task.title;
        renameInput.disabled = activeProjectArchived;
        const renameButton = document.createElement('button');
        renameButton.type = 'submit';
        renameButton.textContent = 'Rename task';
        renameButton.disabled = activeProjectArchived;
        renameForm.append(renameInput, renameButton);
        renameForm.addEventListener('submit', async event => {
          event.preventDefault();
          const newTitle = renameInput.value.trim();
          if (!newTitle) {
            taskAlert.textContent = 'Task title is required';
            renameInput.focus();
            return;
          }
          const result = await fetch(`/api/tasks/${task.id}/rename`, {
            method: 'POST', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ title: newTitle })
          });
          if (result.ok) {
            taskAlert.textContent = '';
            await loadTasks();
          }
        });
        row.append(checkbox, title, renameForm);
        return row;
      }));
    }

    function navigate(path) {
      history.pushState({}, '', path);
      render();
    }

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) await showProject(match[1]);
      else await showList();
    }

    document.querySelector('#create-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#project-name');
      const name = input.value.trim();
      if (!name) {
        alertBox.textContent = 'Project name is required';
        input.focus();
        return;
      }
      const response = await fetch('/api/projects', {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (response.ok) {
        input.value = '';
        alertBox.textContent = '';
        await showList();
      }
    });
    document.querySelector('#back').addEventListener('click', () => navigate('/'));
    document.querySelector('#rename-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#new-project-name');
      const name = input.value.trim();
      const message = document.querySelector('#rename-alert');
      if (!name) {
        message.textContent = 'Project name is required';
        input.focus();
        return;
      }
      const response = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/rename`, {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (response.ok) {
        document.querySelector('#detail-name').textContent = name;
        input.value = '';
        message.textContent = '';
      }
    });
    document.querySelector('#task-filter').addEventListener('change', loadTasks);
    document.querySelector('#project-filter').addEventListener('change', showList);
    document.querySelector('#task-form').addEventListener('submit', async event => {
      event.preventDefault();
      const input = document.querySelector('#task-title-input');
      const title = input.value.trim();
      if (!title) {
        taskAlert.textContent = 'Task title is required';
        input.focus();
        return;
      }
      const response = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`, {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
      });
      if (response.ok) {
        input.value = '';
        taskAlert.textContent = '';
        await loadTasks();
      }
    });
    window.addEventListener('popstate', render);
    render();
  </script>
</body>
</html>

